    'def.collection',
    'return.module', 
    'assert.test',
    'import.utils',
    'class.namespace',
    'lambda.x',
]

test_cases_valid = [
    ('my_ns.my_coll', True),
    ('ansible.builtin', True),
    ('_ns.name', True),
    ('ns_name.', False),  
    ('.name', False),     
    ('a..b', False),      
    ('a.b.c', False),     
]

all_pass = True
